mapper.select:
SELECT

FROM notification n
INNER JOIN `user` u ON u.id = n.actor_id AND u.is_deleted = 0
WHERE n.user_id = #{userId}

    AND n.is_read = 0


    AND (n.create_time < #{cursorCreateTime}
    OR (n.create_time = #{cursorCreateTime} AND n.id < #{cursorId}))

ORDER BY n.create_time DESC, n.id DESC
LIMIT #{limit}

mapper.update:
UPDATE notification
SET is_read = 1
WHERE id = #{notificationId}
  AND user_id = #{userId}
  AND is_read = 0
